code_examples.code:
:root {
  --primary: #1f4e9c;   /* blue: trust */
  --secondary: #5aa9e6; /* analogous lighter blue */
  --accent: #f2a541;    /* complementary orange for buttons/icons */
  --text: #1b1b1b;
  --bg: #ffffff;
}
body { background: var(--bg); color: var(--text); }
button { background: var(--accent); color: var(--text); }
